import{_ as n,o as t,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Sequence Diagram Rules — BrandHub","description":"","frontmatter":{},"headers":[],"relativePath":"feature/system-maintenance/definition/sequence-diagram-rules.md","filePath":"feature/system-maintenance/definition/sequence-diagram-rules.md"}'),a={name:"feature/system-maintenance/definition/sequence-diagram-rules.md"};function c(s,e,h,r,l,d){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="sequence-diagram-rules-—-brandhub" tabindex="-1">Sequence Diagram Rules — BrandHub <a class="header-anchor" href="#sequence-diagram-rules-—-brandhub" aria-label="Permalink to &quot;Sequence Diagram Rules — BrandHub&quot;">​</a></h1><p>&gt; Chuẩn vẽ <code>report4_sequence.drawio</code> cho mọi FR. Áp dụng khi tạo mới hoặc sửa lại sequence diagram. Tham chiếu mẫu chuẩn: <code>profile/3-3-1-view-user-profile/report4_sequence.drawio</code>.</p><hr><h2 id="_1-lifeline-bat-buoc" tabindex="-1">1. Lifeline bắt buộc <a class="header-anchor" href="#_1-lifeline-bat-buoc" aria-label="Permalink to &quot;1. Lifeline bắt buộc&quot;">​</a></h2><p>Mỗi diagram phải có đủ các tầng sau, theo đúng thứ tự trái → phải:</p><ol><li><strong>«Actor»</strong> — người dùng (User, Agency member, ...).</li><li><strong>«Boundary» — UI screen</strong> — trang/màn hình frontend thực tế (ví dụ <code>ProfilePage (UI)</code>, <code>AgenciesPage (UI)</code>). Actor <strong>không bao giờ</strong> gọi thẳng Controller — luôn phải qua 1 UI lifeline trung gian, vì thực tế người dùng tương tác với màn hình, màn hình mới gọi API.</li><li><strong>«Boundary» — Controller</strong> — class <code>*Controller</code> thật trong code.</li><li><strong>«Control» — ServiceImpl</strong> — class <code>*ServiceImpl</code> thật xử lý business logic.</li><li><strong>«Entity» — Repository</strong> — mỗi repository thật được gọi (<code>*Repository</code>).</li><li><strong>«Entity» — Model object</strong> — đối tượng domain model mà repository trả về/mà Service dựng lên (ví dụ <code>User</code>, <code>ClientProfile</code>, <code>Agency</code>, <code>UserSystemRole</code>). <strong>Bắt buộc lifeline riêng, không gộp vào Repository.</strong></li><li><strong>«Entity» — Response object</strong> — DTO trả về cuối cùng (<code>UserProfileResponse</code>, <code>ClientProfileResponse</code>, ...). <strong>Bắt buộc lifeline riêng</strong>, Service phải gửi message <code>new XxxResponse(...)</code> hoặc <code>toResponse(...)</code> tới lifeline này rồi nhận lại object, không trả thẳng từ Service ra Controller.</li><li><strong>«External Service»</strong> (nếu có) — dịch vụ ngoài (FileStorageService, MailService, Redis, JwtUtil, ...).</li></ol><p>Không được thiếu bất kỳ tầng nào ở trên nếu code thật có gọi tới nó.</p><hr><h2 id="_2-repository-call-→-model-object-bat-buoc-2-buoc" tabindex="-1">2. Repository call → Model object (bắt buộc 2 bước) <a class="header-anchor" href="#_2-repository-call-→-model-object-bat-buoc-2-buoc" aria-label="Permalink to &quot;2. Repository call → Model object (bắt buộc 2 bước)&quot;">​</a></h2><p>Không vẽ tắt <code>Repository -&gt; trả thẳng entity đã map</code>. Phải vẽ đủ 2 bước:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service -&gt; Repository: findById(...)</span></span>
<span class="line"><span>Repository -&gt; Service: Optional&lt;Row&gt;          (hoặc &quot;Optional.empty()&quot; nhánh lỗi)</span></span>
<span class="line"><span>Service -&gt; ModelObject: map row -&gt; User        (chỉ khi có dữ liệu)</span></span>
<span class="line"><span>ModelObject -&gt; Service: User</span></span></code></pre></div><p>Áp dụng cho <strong>mọi</strong> repository call có trả dữ liệu — không chỉ call đầu tiên trong flow.</p><hr><h2 id="_3-response-object-dung-o-cuoi-bat-buoc" tabindex="-1">3. Response object dựng ở cuối (bắt buộc) <a class="header-anchor" href="#_3-response-object-dung-o-cuoi-bat-buoc" aria-label="Permalink to &quot;3. Response object dựng ở cuối (bắt buộc)&quot;">​</a></h2><p>Trước khi trả kết quả về Controller, Service phải gửi message tới lifeline Response object:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service -&gt; ResponseObject: new UserProfileResponse(user, role, workspaceId, ...)</span></span>
<span class="line"><span>ResponseObject -&gt; Service: UserProfileResponse</span></span>
<span class="line"><span>Service -&gt; Controller: UserProfileResponse</span></span></code></pre></div><p>Không trả thẳng &quot;UserProfileResponse&quot; từ Service mà không qua lifeline Response.</p><hr><h2 id="_4-khong-request-response-mo-coi-trong-alt-opt" tabindex="-1">4. Không request/response mồ côi trong ALT/OPT <a class="header-anchor" href="#_4-khong-request-response-mo-coi-trong-alt-opt" aria-label="Permalink to &quot;4. Không request/response mồ côi trong ALT/OPT&quot;">​</a></h2><p>Mỗi nhánh của khối ALT hoặc OPT phải có <strong>request + response độc lập của riêng nó</strong> — không dùng chung 1 request vẽ từ ngoài khối rồi để nhánh sau chỉ hiện response mà không có request tương ứng.</p><p>Sai:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service -&gt; Repo: findByUserId(...)     (vẽ 1 lần, ngoài ALT)</span></span>
<span class="line"><span>ALT [no record]</span></span>
<span class="line"><span>  Repo -&gt; Service: Optional.empty()</span></span>
<span class="line"><span>ELSE [record exists]</span></span>
<span class="line"><span>  Repo -&gt; Service: UserSystemRole      (mồ côi — không có request riêng)</span></span></code></pre></div><p>Đúng: mỗi nhánh gọi lại <code>findByUserId(...)</code> độc lập, có cặp request/response riêng.</p><hr><h2 id="_5-activation-bar-tach-theo-nhanh" tabindex="-1">5. Activation bar tách theo nhánh <a class="header-anchor" href="#_5-activation-bar-tach-theo-nhanh" aria-label="Permalink to &quot;5. Activation bar tách theo nhánh&quot;">​</a></h2><p>Khi 1 khối ALT có các nhánh với độ dài xử lý khác nhau (ví dụ nhánh throw kết thúc sớm, nhánh còn lại tiếp tục xử lý dài), activation bar của lifeline Service/Control <strong>phải tách riêng theo từng nhánh</strong> — không vẽ 1 activation bar duy nhất bao trùm cả khối ALT.</p><p>Sai: 1 activation bar cao bằng cả khối ALT (throw-branch + success-branch). Đúng: activation bar riêng cho throw-branch (ngắn, dừng đúng lúc throw), activation bar riêng cho success-branch (dài hơn, hết block).</p><hr><h2 id="_6-condition-label-phai-co-nen-đuc" tabindex="-1">6. Condition label phải có nền đục <a class="header-anchor" href="#_6-condition-label-phai-co-nen-đuc" aria-label="Permalink to &quot;6. Condition label phải có nền đục&quot;">​</a></h2><p>Label điều kiện <code>[...]</code> trong ALT/OPT (tab label và divider label) phải có <code>fillColor</code> đục để không bị lifeline dashed cắt ngang qua chữ:</p><ul><li>Tab ALT/OPT: <code>fillColor=#f5f5f5</code> (khớp màu tab).</li><li>Divider (nhánh else/nhánh tiếp theo): <code>fillColor=#ffffff</code>, <code>strokeColor=none</code>.</li></ul><p>Không để condition label với <code>fillColor</code> trong suốt.</p><hr><h2 id="_7-lifeline-phai-dai-đung-bang-flow-thuc-te" tabindex="-1">7. Lifeline phải dài đúng bằng flow thực tế <a class="header-anchor" href="#_7-lifeline-phai-dai-đung-bang-flow-thuc-te" aria-label="Permalink to &quot;7. Lifeline phải dài đúng bằng flow thực tế&quot;">​</a></h2><p>Vẽ theo 2 pass:</p><ol><li>Tính toàn bộ y-coordinate của message/frame trước (không vẽ lifeline ngay).</li><li>Sau khi có <code>used_bottom</code> (y cuối cùng thực tế), mới vẽ lifeline dài từ <code>y=82</code> tới <code>used_bottom</code>.</li></ol><p>Không dùng hằng số cố định đoán trước — lifeline ngắn hơn nội dung thực tế là lỗi.</p><hr><h2 id="_8-mot-fr-mot-flow-lien-tuc-khong-chia-đoan-flow-a-flow-b" tabindex="-1">8. Một FR = một flow liên tục (không chia đoạn &quot;Flow A/Flow B&quot;) <a class="header-anchor" href="#_8-mot-fr-mot-flow-lien-tuc-khong-chia-đoan-flow-a-flow-b" aria-label="Permalink to &quot;8. Một FR = một flow liên tục (không chia đoạn &quot;Flow A/Flow B&quot;)&quot;">​</a></h2><p>Nếu tài liệu <code>sequence-flow.md</code> mô tả nhiều &quot;Flow&quot; chỉ để chia đoạn diễn giải (không phải nhiều route/endpoint khác nhau), <strong>không</strong> vẽ thành các đoạn tách biệt có ghi chú &quot;Flow A&quot;/&quot;Flow B&quot; trên diagram — vẽ liền mạch thành 1 sequence duy nhất.</p><h3 id="_8a-khi-fr-co-nhieu-route-endpoint-con-that-khac-nhau-vi-du-put-users-me-va-post-users-me-avatar" tabindex="-1">8a. Khi FR có nhiều route/endpoint con thật khác nhau (ví dụ <code>PUT /users/me</code> và <code>POST /users/me/avatar</code>) <a class="header-anchor" href="#_8a-khi-fr-co-nhieu-route-endpoint-con-that-khac-nhau-vi-du-put-users-me-va-post-users-me-avatar" aria-label="Permalink to &quot;8a. Khi FR có nhiều route/endpoint con thật khác nhau (ví dụ \`PUT /users/me\` và \`POST /users/me/avatar\`)&quot;">​</a></h3><p>Gộp thành <strong>1 request tượng trưng duy nhất</strong> từ Actor → UI → Controller, rồi dùng khối <strong>ALT ngay sau khi vào Controller</strong> để rẽ nhánh gọi đúng Service method thật của từng action con:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User -&gt; UI: (hành động chung)</span></span>
<span class="line"><span>UI -&gt; Controller: (1 request tượng trưng)</span></span>
<span class="line"><span>ALT [action con 1]</span></span>
<span class="line"><span>  Controller -&gt; Service: updateUserProfile(...)</span></span>
<span class="line"><span>  ... (toàn bộ logic thật của action 1, giữ đúng method/entity)</span></span>
<span class="line"><span>ELSE [action con 2]</span></span>
<span class="line"><span>  Controller -&gt; Service: updateAvatar(...)</span></span>
<span class="line"><span>  ... (toàn bộ logic thật của action 2, giữ đúng method/entity)</span></span></code></pre></div><p>Quy tắc này ưu tiên gọn hình, <strong>được phép không khớp 100% với route/HTTP method thật</strong> (khác path, khác verb) — nhưng <strong>toàn bộ logic bên trong mỗi nhánh</strong> (tên method Service, Repository, Model, Response, error code) vẫn phải đúng 100% với code thật, không được bịa.</p><h3 id="_8b-khi-cac-flow-trong-tai-lieu-chi-la-cac-nhanh-business-logic-that-nam-trong-cung-1-method-service-vi-du-nhanh-tim-thay-khong-tim-thay" tabindex="-1">8b. Khi các &quot;Flow&quot; trong tài liệu chỉ là các nhánh business logic thật nằm trong CÙNG 1 method Service (ví dụ nhánh tìm thấy/không tìm thấy) <a class="header-anchor" href="#_8b-khi-cac-flow-trong-tai-lieu-chi-la-cac-nhanh-business-logic-that-nam-trong-cung-1-method-service-vi-du-nhanh-tim-thay-khong-tim-thay" aria-label="Permalink to &quot;8b. Khi các &quot;Flow&quot; trong tài liệu chỉ là các nhánh business logic thật nằm trong CÙNG 1 method Service (ví dụ nhánh tìm thấy/không tìm thấy)&quot;">​</a></h3><p>Không cần gộp gì thêm — đây vốn đã là 1 flow, chỉ cần áp khối ALT/OPT theo mục 4 và 5.</p><hr><h2 id="_9-đoi-chieu-code-that-la-bat-buoc" tabindex="-1">9. Đối chiếu code thật là bắt buộc <a class="header-anchor" href="#_9-đoi-chieu-code-that-la-bat-buoc" aria-label="Permalink to &quot;9. Đối chiếu code thật là bắt buộc&quot;">​</a></h2><p>Trước khi vẽ, luôn phải:</p><ol><li>Đọc <code>sequence-flow.md</code> cùng thư mục FR.</li><li>Grep/Read code thật (<code>*Controller</code>, <code>*ServiceImpl</code>, <code>*Repository</code>, model, response DTO) để xác nhận: tên method đúng, thứ tự gọi đúng, entity nào thật sự tồn tại, field nào thật sự trả về.</li><li>Không bịa method/entity không có trong code — nếu tài liệu và code lệch nhau, ưu tiên code thật, có thể ghi chú khác biệt nhưng không tự sửa business logic.</li></ol><hr><h2 id="_10-validate-truoc-khi-coi-la-xong" tabindex="-1">10. Validate trước khi coi là xong <a class="header-anchor" href="#_10-validate-truoc-khi-coi-la-xong" aria-label="Permalink to &quot;10. Validate trước khi coi là xong&quot;">​</a></h2><p>Sau khi vẽ (hoặc sinh bằng script), luôn chạy:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import xml.etree.ElementTree as ET; ET.parse(&#39;&lt;path&gt;.drawio&#39;)&quot;</span></span></code></pre></div><p>XML phải parse sạch không lỗi. Ký tự đặc biệt (<code>&lt;</code>, <code>&gt;</code>, <code>&quot;</code>, <code>&amp;</code>, <code>&lt;br&gt;</code>) trong <code>value=&quot;...&quot;</code> phải được escape (<code>&amp;lt;</code>, <code>&amp;gt;</code>, <code>&amp;quot;</code>, <code>&amp;amp;</code>, <code>&amp;lt;br&amp;gt;</code>).</p><hr><h2 id="_11-khong-tu-commit" tabindex="-1">11. Không tự commit <a class="header-anchor" href="#_11-khong-tu-commit" aria-label="Permalink to &quot;11. Không tự commit&quot;">​</a></h2><p>Không tự <code>git add</code>/commit các file <code>.drawio</code> — người dùng tự commit.</p>`,58)])])}const u=n(a,[["render",c]]);export{g as __pageData,u as default};
